Object.assign(SNIP,{"h25khuon": "int dx[] = {-1, 1, 0, 0}, dy[] = {0, 0, -1, 1};\nvector<vector<int>> d(R, vector<int>(C, -1));\nqueue<pair<int, int>> q;\nd[sr][sc] = 0;\nq.push({sr, sc});\nwhile (!q.empty()) {\n    int r = q.front().first, c = q.front().second;\n    q.pop();\n    for (int k = 0; k < 4; k++) {\n        int nr = r + dx[k], nc = c + dy[k];\n        if (nr < 0 || nr >= R || nc < 0 || nc >= C) continue;   // ra ngoài bảng\n        if (g[nr][nc] == '#' || d[nr][nc] != -1) continue;      // tường hoặc đã thăm\n        d[nr][nc] = d[r][c] + 1;\n        q.push({nr, nc});\n    }\n}"});PRESET_NOTES["l25"]={"Ví dụ: Đếm đảo": "Ba đảo: khối 2 × 2 góc trên trái, khối ở góc phải giữa, và ô đơn lẻ ở hàng cuối. Bảng tham ghi số thứ tự đảo của từng ô.", "Ví dụ: Đường ngắn nhất trong mê cung": "Từ S tới E cần 5 bước, vòng xuống dưới bức tường ở cột 3. Ô d = −1 là ô chưa tới được.", "Ví dụ: Lửa cháy lan từ nhiều điểm": "Hai đám cháy ở hai góc đối nhau; sau 3 phút mọi ô đều cháy. d[ô] là khoảng cách tới đám cháy gần nhất."};EX_HINTS["l25"]=[["Code mẫu loang bằng DFS đệ quy: đảo hình con rắn dài làm đệ quy sâu hàng nghìn tầng, tràn ngăn xếp.", "Dùng BFS với queue<pair<int, int>>: mỗi ô đất chưa thăm mở một đảo mới.", "Đánh dấu tham ngay khi đưa ô vào hàng đợi."], ["Tìm vị trí S và E khi đọc bảng.", "BFS từ S; d[ô] = −1 là chưa tới. Đáp án d tại E (giữ −1 nếu không tới).", "Kiểm tra ra ngoài bảng trước khi đọc g[nr][nc]."], ["Code mẫu BFS riêng từ từng ô cháy (chậm khi nhiều nguồn) và quên trường hợp ô cây bị đá bao quanh.", "Đưa mọi ô F vào hàng đợi với d = 0 rồi BFS một lần: d là thời điểm mỗi ô bắt lửa.", "Còn ô “.” có d = −1 thì in −1; ngược lại in giá trị d lớn nhất."]];
