const PR25=[{label:"Ví dụ: Đếm đảo",input:"",code:"#include <bits/stdc++.h>\nusing namespace std;\n\nint main() {\n    vector<string> g = {\"11000\", \"11010\", \"00011\", \"10000\"};\n    int R = g.size(), C = g[0].size(), dao = 0;\n    int dx[] = {-1, 1, 0, 0}, dy[] = {0, 0, -1, 1};\n    vector<vector<int>> tham(R, vector<int>(C, 0));\n    for (int i = 0; i < R; i++)\n        for (int j = 0; j < C; j++) {\n            if (g[i][j] != '1' || tham[i][j]) continue;\n            dao++;                     // ô đất chưa thăm: một đảo mới\n            queue<pair<int, int>> q;\n            tham[i][j] = dao;\n            q.push({i, j});\n            while (!q.empty()) {\n                int r = q.front().first, c = q.front().second;\n                q.pop();\n                for (int k = 0; k < 4; k++) {\n                    int nr = r + dx[k], nc = c + dy[k];\n                    if (nr < 0 || nr >= R || nc < 0 || nc >= C) continue;\n                    if (g[nr][nc] != '1' || tham[nr][nc]) continue;\n                    tham[nr][nc] = dao;\n                    q.push({nr, nc});\n                }\n            }\n        }\n    cout << dao << \"\\n\";\n    return 0;\n}",viz:[{type:"grid",of:"tham",ptr:["r","c"]}]},{label:"Ví dụ: Đường ngắn nhất trong mê cung",input:"",code:"#include <bits/stdc++.h>\nusing namespace std;\n\nint main() {\n    vector<string> g = {\"S.#.\", \"..#.\", \"...E\", \"#...\"};\n    int R = 4, C = 4;\n    int dx[] = {-1, 1, 0, 0}, dy[] = {0, 0, -1, 1};\n    vector<vector<int>> d(R, vector<int>(C, -1));\n    queue<pair<int, int>> q;\n    d[0][0] = 0;\n    q.push({0, 0});\n    while (!q.empty()) {\n        int r = q.front().first, c = q.front().second;\n        q.pop();\n        for (int k = 0; k < 4; k++) {\n            int nr = r + dx[k], nc = c + dy[k];\n            if (nr < 0 || nr >= R || nc < 0 || nc >= C) continue;\n            if (g[nr][nc] == '#' || d[nr][nc] != -1) continue;\n            d[nr][nc] = d[r][c] + 1;\n            q.push({nr, nc});\n        }\n    }\n    cout << d[2][3] << \"\\n\";\n    return 0;\n}",viz:[{type:"grid",of:"d",ptr:["r","c"]}]},{label:"Ví dụ: Lửa cháy lan từ nhiều điểm",input:"",code:"#include <bits/stdc++.h>\nusing namespace std;\n\nint main() {\n    vector<string> g = {\"F...\", \"....\", \"...F\"};\n    int R = 3, C = 4, lau = 0;\n    int dx[] = {-1, 1, 0, 0}, dy[] = {0, 0, -1, 1};\n    vector<vector<int>> d(R, vector<int>(C, -1));\n    queue<pair<int, int>> q;\n    for (int i = 0; i < R; i++)\n        for (int j = 0; j < C; j++)\n            if (g[i][j] == 'F') { d[i][j] = 0; q.push({i, j}); }   // mọi nguồn vào hàng đợi trước\n    while (!q.empty()) {\n        int r = q.front().first, c = q.front().second;\n        q.pop();\n        lau = max(lau, d[r][c]);\n        for (int k = 0; k < 4; k++) {\n            int nr = r + dx[k], nc = c + dy[k];\n            if (nr < 0 || nr >= R || nc < 0 || nc >= C || d[nr][nc] != -1) continue;\n            d[nr][nc] = d[r][c] + 1;\n            q.push({nr, nc});\n        }\n    }\n    cout << lau << \"\\n\";\n    return 0;\n}",viz:[{type:"grid",of:"d",ptr:["r","c"]}]}];
