makeEx2(document.getElementById("ex-l25"),sim25,[{t:"Đếm đảo",d:"File DEMDAO.INP: dòng 1 là R, C (1 ≤ R, C ≤ 1000); R dòng sau mỗi dòng C ký tự 0 (nước) hoặc 1 (đất). Hai ô đất chung cạnh thuộc cùng một đảo. Ghi vào DEMDAO.OUT số đảo.",tests:[{in:"4 5\n11000\n11010\n00011\n10000",out:"3"},{in:"1 1\n0",out:"0"},{in:"1 1\n1",out:"1"},{in:"3 3\n101\n010\n101",out:"5"},{in:"20 30\n100100101110100000011110010111\n110010110110110110111001110111\n100011011000111101101010000110\n110010101001100111100100011011\n010011101101101100111110110011\n111001000010001001001000101101\n110100111010001011001101111010\n111011110011001101111101010110\n111011010111101101000000111000\n011101010101101101001100100000\n111010011001001000100110000000\n010000000000000011111010100111\n111110010100000001110111010100\n101101101001100001011100111001\n011100100111100110010001101100\n010001111100111011011010010011\n011000010101101010101100101011\n010011010101010011111010011000\n111100011101011111000011010101\n111110111000100100001010001110",out:"35"},{in:"41 30\n111111111111111111111111111111\n000000000000000000000000000001\n111111111111111111111111111111\n100000000000000000000000000000\n111111111111111111111111111111\n000000000000000000000000000001\n111111111111111111111111111111\n100000000000000000000000000000\n111111111111111111111111111111\n000000000000000000000000000001\n111111111111111111111111111111\n100000000000000000000000000000\n111111111111111111111111111111\n000000000000000000000000000001\n111111111111111111111111111111\n100000000000000000000000000000\n111111111111111111111111111111\n000000000000000000000000000001\n111111111111111111111111111111\n100000000000000000000000000000\n111111111111111111111111111111\n000000000000000000000000000001\n111111111111111111111111111111\n100000000000000000000000000000\n111111111111111111111111111111\n000000000000000000000000000001\n111111111111111111111111111111\n100000000000000000000000000000\n111111111111111111111111111111\n000000000000000000000000000001\n111111111111111111111111111111\n100000000000000000000000000000\n111111111111111111111111111111\n000000000000000000000000000001\n111111111111111111111111111111\n100000000000000000000000000000\n111111111111111111111111111111\n000000000000000000000000000001\n111111111111111111111111111111\n100000000000000000000000000000\n111111111111111111111111111111",out:"1"}],start:"#include <bits/stdc++.h>\nusing namespace std;\n\nint R, C;\nvector<string> g;\nvector<vector<bool>> tham;\n\nvoid loang(int r, int c) {             // DFS đệ quy: sâu tới R · C tầng\n    if (r < 0 || r >= R || c < 0 || c >= C || g[r][c] != '1' || tham[r][c]) return;\n    tham[r][c] = true;\n    loang(r + 1, c); loang(r - 1, c); loang(r, c + 1); loang(r, c - 1);\n}\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    if (fopen(\"DEMDAO.INP\", \"r\")) {\n        freopen(\"DEMDAO.INP\", \"r\", stdin);\n        freopen(\"DEMDAO.OUT\", \"w\", stdout);\n    }\n    cin >> R >> C;\n    g.resize(R);\n    for (auto& s : g) cin >> s;\n    tham.assign(R, vector<bool>(C, false));\n    int dao = 0;\n    for (int i = 0; i < R; i++)\n        for (int j = 0; j < C; j++)\n            if (g[i][j] == '1' && !tham[i][j]) { dao++; loang(i, j); }\n    cout << dao << \"\\n\";\n    return 0;\n}",file:"DEMDAO",perf:{gen:n=>{const R=n>>3||1,C=8;const g=[];for(let i=0;i<R;i++){let s="";for(let j=0;j<C;j++)s+=(i%2===0||j===((i>>1)%2===0?C-1:0))?"1":"0";g.push(s)}return R+" "+C+"\n"+g.join("\n")},ns:[400,1600,6400],need:"n",limit:n=>200*n+5000,why:"BFS thăm mỗi ô một lần: O(R · C)."}},{t:"Mê cung",d:"File MECUNG.INP: dòng 1 là R, C (1 ≤ R, C ≤ 1000); R dòng sau mỗi dòng C ký tự: “.” ô trống, “#” tường, “S” vị trí xuất phát, “E” lối ra (đúng một S, một E). Mỗi bước sang một ô chung cạnh không phải tường. Ghi vào MECUNG.OUT số bước ít nhất từ S tới E, hoặc −1 nếu không tới được.",tests:[{in:"4 4\nS.#.\n..#.\n...E\n#...",out:"5"},{in:"1 2\nSE",out:"1"},{in:"1 3\nS#E",out:"-1"},{in:"4 4\nS...\n###.\nE...\n....",out:"8"},{in:"12 15\nS#.....#.....#.\n..#...#.....#.#\n...#.......#.#.\n......#........\n....#..##.#...#\n......##....#..\n.#..#.........#\n....#.#..#.##.#\n..#...#........\n....#####.....#\n.#..#.#.#......\n.#..#.##.#..#.E",out:"25"},{in:"20 20\nS...##.....#........\n...#.#..#...#....#..\n...#.....###..#.#.#.\n#..#.##.#..###.#.#..\n#.#.##.....#......##\n...........###..#..#\n.....#.....#..##..#.\n.###..#....#..###.#.\n....#.#....##....###\n.#..#.#.....#...#..#\n......#...##..#..##.\n....#......#.#.#....\n.....##...#.##....#.\n#..#....##.##.....#.\n#.......#..#..#.##..\n...#...#...#.....#..\n....#####....##.#..#\n#.#..#.###..##....#.\n..#...##.##.#.#.#.#.\n#............#.#...E",out:"48"}],start:"#include <bits/stdc++.h>\nusing namespace std;\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    if (fopen(\"MECUNG.INP\", \"r\")) {\n        freopen(\"MECUNG.INP\", \"r\", stdin);\n        freopen(\"MECUNG.OUT\", \"w\", stdout);\n    }\n    int R, C;\n    cin >> R >> C;\n    vector<string> g(R);\n    for (auto& s : g) cin >> s;\n    // BFS từ ô S; ô E không tới được thì in -1\n    cout << -1 << \"\\n\";\n    return 0;\n}",file:"MECUNG"},{t:"Cháy rừng",d:"File CHAYRUNG.INP: dòng 1 là R, C (1 ≤ R, C ≤ 1000); R dòng sau mỗi dòng C ký tự: “F” ô đang cháy (có ít nhất một), “.” ô cây, “#” ô đá (không cháy, không cho lửa đi qua). Mỗi phút lửa lan từ ô cháy sang mọi ô cây chung cạnh. Ghi vào CHAYRUNG.OUT số phút để mọi ô cây đều cháy, hoặc −1 nếu có ô cây không bao giờ cháy.",tests:[{in:"3 4\nF...\n....\n...F",out:"2"},{in:"1 1\nF",out:"0"},{in:"1 3\nF#.",out:"-1"},{in:"3 3\n.#F\n...\nF#.",out:"2"},{in:"15 20\n...#.....#..........\n..........#....#.#..\n.......#...#........\n.................#..\n.#..................\n.#..........F.......\n..#.................\n...#.....##.........\n....................\n...#........#...#...\n.#.............#.###\n.#.....##...F#..#...\n#F.#..#..#.........#\n..............#...#.\n#..#................",out:"-1"},{in:"25 25\n.................#.......\n.......#....#..#.....#...\n.........................\n.........................\n.........................\n..#........#........#....\n........#.....#....#.....\n...................#.....\n.........................\n....#.............F......\n#........................\n..#.................#..#.\n......#..................\n..............#......##..\n.........................\n...........###...#.......\n.............#...........\n.........................\n.....#...................\n.........................\n#..............#......#..\n.................#.......\n....#....................\n.........................\n#........................",out:"32"}],start:"#include <bits/stdc++.h>\nusing namespace std;\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    if (fopen(\"CHAYRUNG.INP\", \"r\")) {\n        freopen(\"CHAYRUNG.INP\", \"r\", stdin);\n        freopen(\"CHAYRUNG.OUT\", \"w\", stdout);\n    }\n    int R, C;\n    cin >> R >> C;\n    vector<string> g(R);\n    for (auto& s : g) cin >> s;\n    int dx[] = {-1, 1, 0, 0}, dy[] = {0, 0, -1, 1};\n    int tot = 0;\n    // BFS riêng từ từng ô cháy rồi lấy min: chậm khi có nhiều ô cháy\n    vector<vector<int>> best(R, vector<int>(C, -1));\n    for (int i = 0; i < R; i++)\n        for (int j = 0; j < C; j++) {\n            if (g[i][j] != 'F') continue;\n            vector<vector<int>> d(R, vector<int>(C, -1));\n            queue<pair<int, int>> q;\n            d[i][j] = 0;\n            q.push({i, j});\n            while (!q.empty()) {\n                int r = q.front().first, c = q.front().second;\n                q.pop();\n                for (int k = 0; k < 4; k++) {\n                    int nr = r + dx[k], nc = c + dy[k];\n                    if (nr < 0 || nr >= R || nc < 0 || nc >= C || g[nr][nc] == '#' || d[nr][nc] != -1) continue;\n                    d[nr][nc] = d[r][c] + 1;\n                    q.push({nr, nc});\n                }\n            }\n            for (int r = 0; r < R; r++)\n                for (int c = 0; c < C; c++)\n                    if (d[r][c] != -1 && (best[r][c] == -1 || d[r][c] < best[r][c])) best[r][c] = d[r][c];\n        }\n    for (int r = 0; r < R; r++)\n        for (int c = 0; c < C; c++)\n            if (g[r][c] == '.') tot = max(tot, best[r][c]);   // SAI: ô không cháy (-1) bị bỏ qua\n    cout << tot << \"\\n\";\n    return 0;\n}",file:"CHAYRUNG"}]);

